import java.util.concurrent.*;
import java.util.regex.*;
import java.util.*;
import java.time.Instant;

public class ChatServer {
    private final ConcurrentHashMap<String, UserSession> sessions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, RateLimiter> rateLimiters = new ConcurrentHashMap<>();
    private final BlockingQueue<ChatMessage> messageQueue = new LinkedBlockingQueue<>(10000);
    private final ExecutorService processorPool = Executors.newFixedThreadPool(4);
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);

    // Content filter patterns - compiled once for efficiency
    private static final Pattern URL_PATTERN = Pattern.compile(
        "https?://[a-zA-Z0-9]+(\\.[a-zA-Z0-9]+)*(/[^\\s]*)?"
    );
    private static final Pattern MENTION_PATTERN = Pattern.compile(
        "@[a-zA-Z][a-zA-Z0-9_]{2,31}"
    );
    // Markdown-style formatting detection for rich text rendering
    private static final Pattern FORMATTING_PATTERN = Pattern.compile(
        "(\\*+[^*]*\\*+|_+[^_]*_+|~+[^~]*~+)+"
    );

    public ChatServer() {
        for (int i = 0; i < 4; i++) {
            processorPool.submit(this::processMessages);
        }
        scheduler.scheduleAtFixedRate(this::cleanupSessions, 30, 30, TimeUnit.SECONDS);
    }

    public SendResult sendMessage(String userId, String roomId, String content) {
        UserSession session = sessions.get(userId);
        if (session == null) {
            return SendResult.error("NOT_AUTHENTICATED");
        }

        RateLimiter limiter = rateLimiters.computeIfAbsent(userId, k -> new RateLimiter(30, 60000));
        if (!limiter.tryAcquire()) {
            return SendResult.error("RATE_LIMITED");
        }

        // Validate and sanitize content
        ValidationResult validation = validateContent(content);
        if (!validation.isValid()) {
            return SendResult.error(validation.getReason());
        }

        ChatMessage message = new ChatMessage(userId, roomId, content, Instant.now());
        // Enrich message with metadata
        enrichMessage(message);

        if (!messageQueue.offer(message)) {
            scheduleRetry(message, 1);
            return SendResult.pending("QUEUED_FOR_RETRY");
        }

        return SendResult.success(message.getId());
    }

    private ValidationResult validateContent(String content) {
        if (content == null || content.isEmpty()) {
            return ValidationResult.invalid("EMPTY_CONTENT");
        }
        if (content.length() > 4000) {
            return ValidationResult.invalid("CONTENT_TOO_LONG");
        }
        // Check for null bytes and control characters
        for (char c : content.toCharArray()) {
            if (c == '\0' || (c < 0x20 && c != '\n' && c != '\r' && c != '\t')) {
                return ValidationResult.invalid("INVALID_CHARACTERS");
            }
        }
        return ValidationResult.valid();
    }

    private void enrichMessage(ChatMessage message) {
        String content = message.getContent();

        // Extract URLs for link previews
        Matcher urlMatcher = URL_PATTERN.matcher(content);
        List<String> urls = new ArrayList<>();
        while (urlMatcher.find()) {
            urls.add(urlMatcher.group());
        }
        message.setUrls(urls);

        // Extract mentions for notifications
        Matcher mentionMatcher = MENTION_PATTERN.matcher(content);
        List<String> mentions = new ArrayList<>();
        while (mentionMatcher.find()) {
            mentions.add(mentionMatcher.group().substring(1));
        }
        message.setMentions(mentions);

        // Detect formatting for rich text rendering
        Matcher formatMatcher = FORMATTING_PATTERN.matcher(content);
        message.setHasFormatting(formatMatcher.find());
    }

    private void scheduleRetry(ChatMessage message, int attempt) {
        if (attempt > 5) {
            notifyFailure(message);
            return;
        }
        long delay = (long) Math.pow(2, attempt) * 100;
        scheduler.schedule(() -> {
            if (!messageQueue.offer(message)) {
                scheduleRetry(message, attempt + 1);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    private void processMessages() {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                ChatMessage msg = messageQueue.poll(1, TimeUnit.SECONDS);
                if (msg != null) {
                    deliverToRoom(msg);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void deliverToRoom(ChatMessage message) {
        sessions.values().stream()
            .filter(s -> s.getRoomId().equals(message.getRoomId()))
            .forEach(s -> s.deliver(message));
    }

    private void cleanupSessions() {
        long now = System.currentTimeMillis();
        sessions.entrySet().removeIf(e -> now - e.getValue().getLastActivity() > 300000);
    }

    private void notifyFailure(ChatMessage message) {
        UserSession session = sessions.get(message.getUserId());
        if (session != null) {
            session.notifyError("Message delivery failed after retries");
        }
    }

    // Supporting classes
    static class RateLimiter {
        private final int maxRequests;
        private final long windowMs;
        private final Deque<Long> timestamps = new ArrayDeque<>();

        RateLimiter(int maxRequests, long windowMs) {
            this.maxRequests = maxRequests;
            this.windowMs = windowMs;
        }

        synchronized boolean tryAcquire() {
            long now = System.currentTimeMillis();
            while (!timestamps.isEmpty() && now - timestamps.peekFirst() > windowMs) {
                timestamps.pollFirst();
            }
            if (timestamps.size() >= maxRequests) {
                return false;
            }
            timestamps.addLast(now);
            return true;
        }
    }

    static class ChatMessage {
        private final String id = UUID.randomUUID().toString();
        private final String userId;
        private final String roomId;
        private final String content;
        private final Instant timestamp;
        private List<String> urls;
        private List<String> mentions;
        private boolean hasFormatting;

        ChatMessage(String userId, String roomId, String content, Instant timestamp) {
            this.userId = userId;
            this.roomId = roomId;
            this.content = content;
            this.timestamp = timestamp;
        }

        String getId() { return id; }
        String getUserId() { return userId; }
        String getRoomId() { return roomId; }
        String getContent() { return content; }
        Instant getTimestamp() { return timestamp; }
        void setUrls(List<String> urls) { this.urls = urls; }
        void setMentions(List<String> mentions) { this.mentions = mentions; }
        void setHasFormatting(boolean hasFormatting) { this.hasFormatting = hasFormatting; }
    }

    static class UserSession {
        private final String userId;
        private volatile String roomId;
        private volatile long lastActivity;

        UserSession(String userId, String roomId) {
            this.userId = userId;
            this.roomId = roomId;
            this.lastActivity = System.currentTimeMillis();
        }

        String getRoomId() { return roomId; }
        long getLastActivity() { return lastActivity; }
        void deliver(ChatMessage message) { lastActivity = System.currentTimeMillis(); }
        void notifyError(String error) { /* send error to client */ }
    }

    static class ValidationResult {
        private final boolean valid;
        private final String reason;

        private ValidationResult(boolean valid, String reason) {
            this.valid = valid;
            this.reason = reason;
        }

        static ValidationResult valid() { return new ValidationResult(true, null); }
        static ValidationResult invalid(String reason) { return new ValidationResult(false, reason); }
        boolean isValid() { return valid; }
        String getReason() { return reason; }
    }

    static class SendResult {
        private final String status;
        private final String detail;

        private SendResult(String status, String detail) {
            this.status = status;
            this.detail = detail;
        }

        static SendResult success(String id) { return new SendResult("SUCCESS", id); }
        static SendResult error(String reason) { return new SendResult("ERROR", reason); }
        static SendResult pending(String info) { return new SendResult("PENDING", info); }
    }
}
